 3	public final class BinarySearch {
 4	    private static final int NOT_FOUND = -1;
 5	    private static final int SAMPLE_TARGET = 10;
 6	    private static final String NOT_FOUND_MESSAGE = "Element is not present in array";
 7	    private static final String FOUND_MESSAGE_PREFIX = "Element is present at index ";
 8	
 9	    private BinarySearch() {
10	    }
11	
12	    /**
13	     * Searches an ascending sorted array and returns the target index, or -1 when absent.
14	     */
15	    public static int binarySearch(int[] sortedValues, int target) {
16	        Objects.requireNonNull(sortedValues, "sortedValues");
17	
18	        int left = 0;
19	        int right = sortedValues.length - 1;
20	
21	        while (left <= right) {
22	            int middle = midpoint(left, right);
23	            int value = sortedValues[middle];
24	
25	            if (value == target) {
26	                return middle;
27	            }
28	
29	            if (value < target) {
30	                left = middle + 1;
31	            } else {
32	                right = middle - 1;
33	            }
34	        }
35	
36	        return NOT_FOUND;
37	    }
38	
39	    private static int midpoint(int left, int right) {
40	        return left + (right - left) / 2;
41	    }
42	
